  "widget.compare.callout": { en: "<strong>{short}:</strong> {direction} association with price (slope = {slope}, R² = {r2pct}%). {compare}Remember: <em>association does not prove causation</em>. Omitted variables (condition, location, school district) could confound any of these relationships.", es: "<strong>{short}:</strong> asociación {direction} con el precio (pendiente = {slope}, R² = {r2pct}%). {compare}Recuerda: <em>asociación no demuestra causalidad</em>. Las variables omitidas (condición, ubicación, distrito escolar) podrían confundir cualquiera de estas relaciones." },
  "widget.compare.callout.compare": { en: "Compare to Size (R² = {sizePct}%). ", es: "Compara con Tamaño (R² = {sizePct}%). " },
  "widget.compare.chart.annotation": { en: "slope = {slope}  ·  R² = {r2pct}%", es: "pendiente = {slope}  ·  R² = {r2pct}%" },
  "widget.compare.chart.hover.house": { en: "{label}: %{x}<br>$%{y:,}<extra></extra>", es: "{label}: %{x}<br>$%{y:,}<extra></extra>" },
