  "widget.predict.callout.base": { en: "<strong>Predicted price at {sz} sq ft:</strong> ${price}.", es: "<strong>Precio pronosticado para {sz} pies²:</strong> ${price}." },
  "widget.predict.callout.diff": { en: " (True OLS would predict ${truePred} — a ${amt} {direction} estimate.)", es: " (La MCO verdadera predeciría ${truePred} — una estimación ${amt} {direction}.)" },
  "widget.predict.callout.warn": { en: " <em>Warning: {sz} sq ft is outside the data range ({min}–{max}). You are extrapolating.</em>", es: " <em>Advertencia: {sz} pies² está fuera del rango de datos ({min}–{max}). Estás extrapolando.</em>" },
